# Generate patterns with different fills
def fill_cardinal_offsets(points, offset=1, value=2, width=17, height=14):
    """Fill line segments from each point outward in 4 directions"""
    grid = np.zeros((height, width), dtype=int)
    for p in points:
        r, c = p

        # Up
        for dr in range(1, min(r, offset) + 1):
            grid[r-dr, c] = value

        # Down
        for dr in range(1, min(height-1-r, offset) + 1):
            grid[r+dr, c] = value

        # Left
        for dc in range(1, min(c, offset) + 1):
            grid[r, c-dc] = value

        # Right
        for dc in range(1, min(width-1-c, offset) + 1):
            grid[r, c+dc] = value
    return grid.tolist()

